const crypto = require('crypto');

// Signs `${timestamp}.${payload}` the same way convex/lib/signature.ts does.
function signedHeaders(payload) {
  const secret = $env.AUTOMATION_SECRET;
  if (!secret) throw new Error('AUTOMATION_SECRET is not set for n8n');
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
  return { 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': `sha256=${digest}` };
}

const path = '/automation/overdue-loans';
return [{ json: { url: `${$env.CONVEX_SITE_URL}${path}`, headers: signedHeaders(path) } }];

// One item per overdue loan. An empty list ends the run here.
return $input.first().json.loans.map((loan) => ({
  json: {
    loanId: loan.loanId,
    reminderKey: loan.reminderKey,
    mail: {
      From: { Email: 'no-reply@lendloop.test', Name: 'LendLoop' },
      To: [{ Email: loan.borrower.email, Name: loan.borrower.firstName }],
      Subject: `Please return the ${loan.toolName}`,
      Text: `Hi ${loan.borrower.firstName},\n\nThe ${loan.toolName} was due back on ${loan.dueDate}, ${loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`} ago. Please return it or get in touch with the lender.\n\nLendLoop`,
    },
  },
}));

// Sends one message through the mail API. Tries three times, waiting a
// little longer each time, and returns the error text if all attempts fail.
async function sendMail(helpers, mail) {
  let lastError;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      await helpers.httpRequest({
        method: 'POST',
        url: `${$env.MAILPIT_URL}/api/v1/send`,
        body: mail,
        json: true,
        timeout: 10000,
      });
      return null;
    } catch (error) {
      lastError = error;
      if (attempt < 3) await new Promise((resolve) => setTimeout(resolve, 2000 * attempt));
    }
  }
  return String(lastError?.message ?? lastError).slice(0, 200);
}

// One loan at a time, so a retry never repeats a message that already went out.
const results = [];
for (const item of $input.all()) {
  const error = await sendMail(this.helpers, item.json.mail);
  results.push({ json: { loanId: item.json.loanId, reminderKey: item.json.reminderKey, error } });
}
return results;

const crypto = require('crypto');

// Signs `${timestamp}.${payload}` the same way convex/lib/signature.ts does.
function signedHeaders(payload) {
  const secret = $env.AUTOMATION_SECRET;
  if (!secret) throw new Error('AUTOMATION_SECRET is not set for n8n');
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
  return { 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': `sha256=${digest}` };
}

// One report per loan. The key is the one Convex issued for this loan and
// day, so reporting the same reminder twice changes nothing.
return $input.all().map((item) => {
  const failed = item.json.error !== null;
  const body = JSON.stringify({
    loanId: item.json.loanId,
    kind: 'reminder',
    key: item.json.reminderKey,
    status: failed ? 'failed' : 'sent',
    detail: failed ? item.json.error : undefined,
  });
  return { json: { body, headers: signedHeaders(body), failed } };
});
